<?php
declare(strict_types=1);
use HomeAlone\{Database,Finance,Scope,Operations};
function seed(Database $db, bool $platformAdmin=true): void {
    if($db->one('SELECT id FROM companies LIMIT 1'))return;
    $db->transaction(function()use($db,$platformAdmin){
        $plan=$db->insert('plans',['id'=>'plan-demo','name'=>'Demonstração','property_limit'=>100,'member_limit'=>30]);
        $db->insert('companies',['id'=>'company-lisbon','slug'=>'casa-lisboa','name'=>'Casa Lisboa','email'=>'equipa@casa-lisboa.example','phone'=>'+351 210 000 000','description'=>'Casas com personalidade. Uma nova forma de viver Lisboa, com espaços cuidados e uma equipa sempre por perto.','plan_id'=>$plan['id']]);
        $db->insert('companies',['id'=>'company-porto','slug'=>'porto-living','name'=>'Porto Living','email'=>'ola@porto-living.example','description'=>'O seu próximo capítulo começa no Porto. Apartamentos para viver ao seu ritmo.']);
        foreach([['u-admin','Mariana Costa','gestor@demo.homealone.pt','ADMIN','company-lisbon'],['u-resident','Inês Martins','morador@demo.homealone.pt','RESIDENT','company-lisbon'],['u-owner','Pedro Almeida','proprietario@demo.homealone.pt','OWNER','company-lisbon'],['u-tech','João Ferreira','tecnico@demo.homealone.pt','TECHNICIAN','company-lisbon'],['u-finance','Sofia Santos','financeiro@demo.homealone.pt','FINANCE','company-lisbon'],['u-porto','Rui Sousa','gestor@demo.porto.pt','ADMIN','company-porto']]as[$id,$name,$email,$role,$company]){$db->insert('users',['id'=>$id,'name'=>$name,'email'=>$email,'password_hash'=>password_hash(bin2hex(random_bytes(24)),PASSWORD_DEFAULT),'platform_admin'=>$platformAdmin&&$id==='u-admin'?1:0]);$db->insert('memberships',['company_id'=>$company,'user_id'=>$id,'role'=>$role]);}
        $photos=['https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=900&q=80','https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=900&q=80','https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=900&q=80','https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=900&q=80'];
        $db->insert('properties',['id'=>'p-building','company_id'=>'company-lisbon','name'=>'Edifício da Estrela','type'=>'BUILDING','address'=>'Rua da Estrela, 24','city'=>'Lisboa','rent_cents'=>0,'owner_id'=>'u-owner']);
        foreach([['p-estrela','Estrela · Apartamento 2A','Estrela, Lisboa',145000,2,92,0],['p-alfama','Alfama · Loft com varanda','Alfama, Lisboa',98000,1,58,1],['p-principe','Príncipe Real · Apartamento 3B','Príncipe Real, Lisboa',180000,3,124,2],['p-graca','Graça · Estúdio luminoso','Graça, Lisboa',85000,0,42,3],['p-arroios','Arroios · Apartamento 1D','Arroios, Lisboa',125000,2,76,1],['p-alcantara','Alcântara · Apartamento 4A','Alcântara, Lisboa',135000,2,84,2]]as[$id,$name,$address,$rent,$beds,$area,$photo])$db->insert('properties',['id'=>$id,'company_id'=>'company-lisbon','name'=>$name,'type'=>'APARTMENT','parent_id'=>$id==='p-estrela'?'p-building':null,'address'=>$address,'city'=>'Lisboa','rent_cents'=>$rent,'bedrooms'=>$beds,'area'=>$area,'owner_id'=>'u-owner','published'=>1,'description'=>'Um espaço pensado para se sentir em casa. Luz natural, materiais acolhedores e uma localização de bairro com tudo por perto. Disponível para arrendamento mensal.','photos'=>json_encode([$photos[$photo]]),'amenities'=>json_encode(['Mobilado','Cozinha equipada','Wi-Fi','Luz natural'])]);
        $db->insert('properties',['id'=>'p-common','company_id'=>'company-lisbon','name'=>'Estrela · Áreas comuns','type'=>'COMMON','parent_id'=>'p-building','address'=>'Rua da Estrela, 24','city'=>'Lisboa','rent_cents'=>0]);
        $db->insert('properties',['id'=>'p-porto','company_id'=>'company-porto','name'=>'Cedofeita · Apartamento T1','type'=>'APARTMENT','address'=>'Cedofeita, Porto','city'=>'Porto','rent_cents'=>90000,'published'=>1,'photos'=>json_encode([$photos[0]])]);
        foreach([['co-ines','Inês Martins','ines@example.test','RESIDENT','u-resident'],['co-miguel','Miguel Oliveira','miguel@example.test','RESIDENT',null],['co-ana','Ana Ribeiro','ana@example.test','RESIDENT',null],['co-tiago','Tiago Lopes','tiago@example.test','RESIDENT',null],['co-beatriz','Beatriz Silva','beatriz@example.test','LEAD',null],['co-diogo','Diogo Ferreira','diogo@example.test','LEAD',null],['co-carolina','Carolina Reis','carolina@example.test','LEAD',null],['co-francisco','Francisco Melo','francisco@example.test','LEAD',null],['co-provider','Repara Lisboa','repara@example.test','PROVIDER',null]]as[$id,$name,$email,$kind,$uid])$db->insert('contacts',['id'=>$id,'company_id'=>'company-lisbon','name'=>$name,'email'=>$email,'kind'=>$kind,'user_id'=>$uid,'phone'=>'+351 910 000 000','tags'=>json_encode($kind==='LEAD'?['Site']:[])]);
        $today=new DateTimeImmutable('now',new DateTimeZone('Europe/Lisbon'));$start=$today->modify('first day of -5 months')->format('Y-m-d');
        foreach([['ct-ines','p-estrela','co-ines',145000,1],['ct-miguel','p-alfama','co-miguel',98000,1],['ct-ana','p-principe','co-ana',180000,5],['ct-tiago','p-arroios','co-tiago',125000,1]]as[$id,$p,$co,$rent,$due]){$db->insert('contracts',['id'=>$id,'company_id'=>'company-lisbon','property_id'=>$p,'start_date'=>$start,'end_date'=>$id==='ct-miguel'?$today->modify('+45 days')->format('Y-m-d'):$today->modify('+10 months')->format('Y-m-d'),'rent_cents'=>$rent,'deposit_cents'=>$rent*2,'due_day'=>$due]);$db->run('INSERT INTO contract_residents(company_id,contract_id,contact_id) VALUES(?,?,?)',['company-lisbon',$id,$co]);$db->insert('deposit_entries',['company_id'=>'company-lisbon','contract_id'=>$id,'kind'=>'RECEIVED','amount_cents'=>$rent*2,'reason'=>'Caução de entrada — demonstração']);}
        $scope=new Scope($db,'company-lisbon',['id'=>'u-admin'],'ADMIN');$finance=new Finance($db);
        for($i=5;$i>=0;$i--){$period=$today->modify('first day of this month')->modify("-$i months")->format('Y-m');$finance->generate($scope,$period);foreach($db->all('SELECT * FROM charges WHERE period=?',[$period])as $ch){$paid=$i>0||$ch['contract_id']==='ct-ines';$partial=$i===0&&$ch['contract_id']==='ct-tiago';if($paid||$partial)$db->insert('payments',['company_id'=>'company-lisbon','charge_id'=>$ch['id'],'amount_cents'=>$partial?60000:$ch['amount_cents'],'kind'=>'PAYMENT','method'=>'MANUAL','reason'=>'Dados fictícios de demonstração','idempotency_key'=>'seed:'.$ch['id'],'created_at'=>$period.'-02 10:00:00']);}}
        foreach([['t-water','p-estrela','Fuga de água na cozinha','O sifão por baixo do lava-loiça está a pingar.','PLUMBING','HIGH','IN_PROGRESS','u-tech'],['t-light','p-common','Iluminação da entrada','A luz da entrada do edifício não acende.','ELECTRICITY','NORMAL','NEW',null],['t-oven','p-alfama','Forno não aquece','O forno liga mas não atinge a temperatura.','APPLIANCE','NORMAL','SCHEDULED','u-tech'],['t-door','p-arroios','Afinação da porta de entrada','A porta precisa de ser afinada.','BUILDING','LOW','RESOLVED','u-tech']]as[$id,$p,$title,$description,$category,$priority,$status,$assignee]){$db->insert('tickets',['id'=>$id,'company_id'=>'company-lisbon','property_id'=>$p,'reporter_id'=>$id==='t-water'?'u-resident':'u-admin','title'=>$title,'description'=>$description,'category'=>$category,'priority'=>$priority,'status'=>$status,'assignee_id'=>$assignee,'due_at'=>$today->modify('+2 days')->format('Y-m-d')]);}
        $db->insert('ticket_notes',['company_id'=>'company-lisbon','ticket_id'=>'t-water','author_id'=>'u-tech','body'=>'Visita agendada para amanhã de manhã. Vou levar um sifão de substituição.']);
        $db->insert('ticket_notes',['company_id'=>'company-lisbon','ticket_id'=>'t-water','author_id'=>'u-admin','body'=>'Confirmar cobertura do prestador antes de aprovar.','internal'=>1]);
        foreach([['co-beatriz','p-graca','NEW'],['co-diogo','p-alcantara','QUALIFIED'],['co-carolina','p-graca','VISIT'],['co-francisco','p-alcantara','PROPOSAL']]as[$co,$p,$stage])$db->insert('leads',['company_id'=>'company-lisbon','contact_id'=>$co,'property_id'=>$p,'stage'=>$stage,'source'=>'website','task'=>$stage==='VISIT'?'Confirmar visita':'Contactar interessado','task_due'=>$today->modify('+1 day')->format('Y-m-d')]);
        $ops=new Operations($db);$conv=$ops->createConversation($scope,['participant_ids'=>['u-resident'],'property_id'=>'p-estrela','subject'=>'Bem-vinda à sua nova casa','body'=>'Olá Inês! Pode usar este espaço para falar connosco. Estamos por aqui para ajudar.']);$ops->send(new Scope($db,'company-lisbon',['id'=>'u-resident'],'RESIDENT'),$conv['id'],['body'=>'Obrigada, Mariana! Já me estou a instalar. Gostei muito da luz da sala.']);
        $db->insert('expenses',['company_id'=>'company-lisbon','property_id'=>'p-arroios','ticket_id'=>'t-door','description'=>'Afinação e manutenção de fechadura','amount_cents'=>8500,'date'=>$today->format('Y-m-d')]);
        $ops->notify('company-lisbon','u-resident','O seu espaço, sempre à mão','Consulte a renda, reporte uma avaria ou envie-nos uma mensagem.','welcome-resident');
    });
}
